// ============================================================
// NODE 3 — BUILD GEMINI PROMPT
// Merges form input + profile + blooms + strategies
// ============================================================

// --- Pull form input — works in both test and live mode ---
const form = $('1. Form Response Trigger').first().json;

// --- Pull profile data ---
const profileRows = $('2a. Read Profile Tab').all().map(i => i.json);
const profile = {};
profileRows.forEach(row => {
  if (row['key'] && row['value']) {
    profile[row['key'].trim()] = String(row['value']).trim();
  }
});

// --- Pull Bloom's data ---
const bloomsRows = $('2b. Read Blooms Tab').all().map(i => i.json);
const bloomsText = bloomsRows.map(r =>
  `${r['level']}: ${r['all_verbs'] || ''}`
).join('\n');

// --- Pull strategies ---
const stratRows = $('2c. Read Strategies Tab').all().map(i => i.json);
const strategiesText = stratRows.map(r =>
  `- ${r['strategy']}: ${r['description']} (Best for: ${r['best_for']})`
).join('\n');

// --- Helper: find field regardless of trailing spaces or dash type ---
const f = (key) => {
  const normalise = s => s.trim().replace(/\u2014/g, '-').replace(/\u2013/g, '-');
  const match = Object.keys(form).find(k => normalise(k) === normalise(key));
  return match ? String(form[match] || '').trim() : '';
};

// --- Helper: convert Google Sheets date serial to YYYY-MM-DD ---
const excelDateToString = (serial) => {
  if (!serial || isNaN(Number(serial))) return String(serial || '');
  const date = new Date((Number(serial) - 25569) * 86400 * 1000);
  return date.toISOString().split('T')[0];
};

// --- Form fields ---
const unitTitle     = f('Unit Title');
const unitCode      = f('Unit Code');
const className     = f('Class Name');
const numLearners   = String(f('Number of Learners'));
const weekNo        = String(f('Week Number'));
const weekDate      = excelDateToString(f('Date of Week (Monday)'));
const skillTask     = f('Skill or Job Task');
const rawObjectives = f('Raw Learning Objectives');
const session1Title = f('Session 1 Title');
const session1Hints = f('Session 1 - Topic Hints');
const session2Title = f('Session 2 Title');
const session2Hints = f('Session 2 - Topic Hints');
const specialInstr  = f('Special Instructions for AI') || 'None';

// --- Debug ---
console.log('session2Title:', JSON.stringify(session2Title));
console.log('session2Title length:', session2Title.length);

const hasSession2 = session2Title.length > 0;
console.log('hasSession2:', hasSession2);

// --- Build the prompt ---
const prompt = `
You are an expert curriculum developer for TVET/college-level education in Kenya.
You write in formal, assessor-ready language aligned to KSTVET standards.
You MUST respond with valid JSON only. No explanation, no markdown, no preamble.
Do NOT use markdown formatting in any field values. No ##, no **, no *, no -- bullets.
For section headings use CAPS. For lists use numbers (1. 2. 3.) or letters (a. b. c.).
Write in flowing, formal prose where possible. This content goes into Google Docs directly.

=== BLOOM'S TAXONOMY VERBS (use these for all learning outcomes) ===
${bloomsText}

For a Level 6 college class, PREFER verbs from levels 3-6 (Applying, Analysing, Evaluating, Creating).
Use levels 1-2 only for introductory or foundational sessions.

=== ACTIVE LEARNING STRATEGIES (use these for Trainee Activities) ===
${strategiesText}

Always name the specific strategy used (e.g. "Through Think-Pair-Share, trainees...").
Each session must use at least 2 different strategies.

=== TEACHER INPUT ===
Unit Title: ${unitTitle}
Unit Code: ${unitCode}
Class: ${className}
Learners: ${numLearners}
Week: ${weekNo}
Skill/Job Task: ${skillTask}
Raw Objectives: ${rawObjectives}
Session 1 Title: ${session1Title}
Session 1 Topic Hints: ${session1Hints}
${hasSession2
  ? `Session 2 Title: ${session2Title}\nSession 2 Topic Hints: ${session2Hints}`
  : 'Session 2: NOT REQUIRED — leave all session_2 fields as empty strings'}
Special Instructions: ${specialInstr}

=== OUTPUT FORMAT ===
Return ONLY this JSON structure. All values must be strings.

{
  "benchmarks": "4 benchmark statements separated by newlines, using Bloom's verbs (Define... / Identify... / Determine... / Apply...)",
  "session_1_outcomes": "3-4 learning outcomes starting with Bloom's verbs, each on a new line, starting with a dash",
  "session_1_keypoints": "Structured key learning points with sub-headings and bullet content, aligned to outcomes",
  "session_1_activities": "Trainee activities naming the strategy used. Format: 'Through [Strategy], trainees will [action].' One per outcome.",
  "session_1_references": "2-3 APA-formatted textbook references relevant to this topic",
  "session_1_resources": "3-5 physical or digital resources (models, images, software, handouts etc.)",
  "session_1_assessment": "Knowledge: [method]\nSkill: [method]\nAttitudes: [method]",
  "session_2_outcomes": "${hasSession2 ? '3-4 outcomes for session 2' : ''}",
  "session_2_keypoints": "${hasSession2 ? 'Key points for session 2' : ''}",
  "session_2_activities": "${hasSession2 ? 'Activities for session 2' : ''}",
  "session_2_references": "${hasSession2 ? 'References for session 2' : ''}",
  "session_2_resources": "${hasSession2 ? 'Resources for session 2' : ''}",
  "session_2_assessment": "${hasSession2 ? 'Assessment for session 2' : ''}"
}
`;

return [{
  json: {
    prompt,
    unit_title: unitTitle,
    unit_code: unitCode,
    class_name: className,
    num_learners: numLearners,
    week_no: weekNo,
    week_date: weekDate,
    skill_task: skillTask,
    session_1_title: session1Title,
    session_2_title: session2Title,
    has_session_2: hasSession2,
    trainer_name: profile['trainer_name'] || '',
    admission_no: profile['admission_no'] || '',
    institution: profile['institution'] || '',
    level: profile['level'] || '6',
    ref_learning_plan: profile['ref_learning_plan'] || 'KSTVET/TP/LP/FO7',
    template_doc_id: profile['learning_plan_template_id'] || '',
    output_folder_id: profile['output_folder_id'] || '',
    date_prepared: new Date().toLocaleDateString('en-GB', { day:'2-digit', month:'short', year:'numeric' })
  }
}];

// NODE 5 — PARSE GEMINI RESPONSE
const rawText = $input.first().json.text;

// Strip markdown code fences
const cleaned = rawText
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

// Parse JSON
let ai;
try {
  ai = JSON.parse(cleaned);
} catch(e) {
  throw new Error('Failed to parse Gemini JSON: ' + cleaned.substring(0, 300));
}

const prev = $('3. Build Gemini Prompt').first().json;

return [{
