  ['{{skill_task}}',            p['{{skill_task}}']],
  ['{{week_no}}',               p['{{week_no}}']],
  ['{{benchmarks}}',            p['{{benchmarks}}']],
  ['{{session_1_title}}',       p['{{session_1_title}}']],
  ['{{session_1_outcomes}}',    p['{{session_1_outcomes}}']],
  ['{{session_1_keypoints}}',   p['{{session_1_keypoints}}']],
  ['{{session_1_activities}}',  p['{{session_1_activities}}']],
  ['{{session_1_references}}',  p['{{session_1_references}}']],
  ['{{session_1_resources}}',   p['{{session_1_resources}}']],
  ['{{session_1_assessment}}',  p['{{session_1_assessment}}']],
  ['{{session_2_title}}',       p['{{session_2_title}}']],
  ['{{session_2_outcomes}}',    p['{{session_2_outcomes}}']],
  ['{{session_2_keypoints}}',   p['{{session_2_keypoints}}']],
  ['{{session_2_activities}}',  p['{{session_2_activities}}']],
  ['{{session_2_references}}',  p['{{session_2_references}}']],
  ['{{session_2_resources}}',   p['{{session_2_resources}}']],
  ['{{session_2_assessment}}',  p['{{session_2_assessment}}']],
];

const requests = placeholders.map(([text, replaceText]) => ({
  replaceAllText: {
    containsText: { text, matchCase: true },
    replaceText: String(replaceText || '')
  }
}));

return [{
  json: {
    docId,
    body: { requests }
  }
}];

// ============================================================
// NODE 3b — BUILD SESSION PLAN GEMINI PROMPT
// ============================================================

const form = $('1. Form Response Trigger').first().json;

// Same helper functions from LP
const f = (key) => {
  const match = Object.keys(form).find(k => k.trim() === key.trim());
  return match ? (form[match] || '') : '';
};

const excelDateToString = (serial) => {
  if (!serial || isNaN(serial)) return String(serial || '');
  const date = new Date((serial - 25569) * 86400 * 1000);
  return date.toISOString().split('T')[0];
};

