const sessionHints    = f('Session Topic Hints');
const lpContext       = f('LP Outcomes and Key Points');
const llnReq          = f('LLN Requirements') || 'N/A';
const specialInstr    = f('Special Instructions for AI') || 'None';

// ============================================================
// PROMPT 1 — SESSION PLAN ONLY
// ============================================================
const promptSP = `
You are an expert curriculum developer for TVET/college-level education in Kenya.
You write in formal, assessor-ready language aligned to KSTVET standards.
You MUST respond with valid JSON only. No explanation, no markdown, no preamble.
Do NOT use markdown formatting in any field values. No ##, no **, no *, no -- bullets.
For section headings use CAPS. For lists use numbers (1. 2. 3.) or letters (a. b. c.).
Write in flowing, formal prose where possible. This content goes into Google Docs directly.

